package com.internhub.entity;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.DBRef; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant;
@Document("audit_logs") public class AuditLog { @Id private Long id; @Indexed private Long adminUserId; @DBRef private User admin; private String action; private String targetType; private Long targetId; private String details; @Indexed private Instant createdAt; public Long getId(){return id;} public void setId(Long v){id=v;} public User getAdmin(){return admin;} public void setAdmin(User v){admin=v;adminUserId=v==null?null:v.getId();} public String getAction(){return action;} public void setAction(String v){action=v;} public String getTargetType(){return targetType;} public void setTargetType(String v){targetType=v;} public Long getTargetId(){return targetId;} public void setTargetId(Long v){targetId=v;} public String getDetails(){return details;} public void setDetails(String v){details=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} }
